// Data access: the live Python API when it is running, otherwise the bundled
// scenario files in public/data (same JSON, generated by export_explorer_data.py).

import type { Scenario } from "./types";

export type Mode = "live" | "bundled";
let mode: Mode | null = null;
let index: { scenarios: Scenario[]; files: Record<string, { op: string; params: Record<string, string> }> } | null = null;
const memo = new Map<string, Promise<any>>();

export class DataUnavailable extends Error {}

async function sha1hex(s: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-1", new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/** Must match key_for() in scripts/export_explorer_data.py. */
export async function keyFor(op: string, params: Record<string, string>): Promise<string> {
  const norm = Object.keys(params).sort().filter((k) => String(params[k]).trim())
    .map((k) => `${k}=${String(params[k]).trim()}`).join("&");
  return `${op}-${(await sha1hex(norm)).slice(0, 10)}`;
}

export async function detectMode(): Promise<Mode> {
  if (mode) return mode;
  try {
    const r = await fetch("api/health", { signal: AbortSignal.timeout(2500) });
    mode = r.ok && (r.headers.get("content-type") ?? "").includes("json") ? "live" : "bundled";
  } catch { mode = "bundled"; }
  return mode;
}

export async function loadIndex() {
  if (!index) index = await (await fetch("data/index.json")).json();
  return index!;
}

export async function call<T = any>(op: string, params: Record<string, string>): Promise<T> {
  const clean = Object.fromEntries(Object.entries(params).filter(([, v]) => String(v ?? "").trim()));
  const key = await keyFor(op, clean);
  if (!memo.has(key)) {
    memo.set(key, (async () => {
      if ((await detectMode()) === "live") {
        const qs = new URLSearchParams(clean).toString();
        const r = await fetch(`api/${op}?${qs}`);
        const body = await r.json();
        if (!r.ok) throw new Error(body.error ?? `HTTP ${r.status}`);
        return body;
      }
      const idx = await loadIndex();
      if (!idx.files[key]) throw new DataUnavailable(
        "This query is not in the bundled demo data. Start the backend (python3 scripts/bpm_api.py) for live queries.");
      return (await fetch(`data/${key}.json`)).json();
    })());
    memo.get(key)!.catch(() => memo.delete(key));
  }
  return memo.get(key)!;
}

export async function bundledQueries(op: string) {
  const idx = await loadIndex();
  return Object.values(idx.files).filter((f) => f.op === op).map((f) => f.params);
}
